#!/bin/zsh
# latency-log.zsh HOST [COUNT] [INTERVAL_SECONDS] [LOGFILE]
host=${1:?usage: latency-log.zsh HOST [COUNT] [INTERVAL_SECONDS] [LOGFILE]}
count=${2:-60}
interval=${3:-5}
log=${4:-latency.csv}

[[ -s $log ]] || print "timestamp,host,rtt_ms" > $log

for (( i = 1; i <= count; i++ )); do
  ts=$(date '+%Y-%m-%dT%H:%M:%S')
  rtt=$(ping -c 1 -t 2 -W 1000 $host 2>/dev/null | awk -F'[= ]' '/time=/ {print $(NF-1)}')
  print "$ts,$host,${rtt:-timeout}" >> $log
  sleep $interval
done

#!/bin/zsh
# latency-summary.zsh [LOGFILE]
log=${1:-latency.csv}
[[ -r $log ]] || { print -u2 "cannot read $log"; exit 1 }

awk -F, 'NR>1 {t++} NR>1 && $3=="timeout" {l++} END {printf "probes=%d lost=%d loss=%.1f%%\n", t, l, (t ? 100*l/t : 0)}' $log

awk -F, 'NR>1 && $3!="timeout" {print $3}' $log | sort -n | awk '
  {v[NR]=$1; s+=$1}
  END {
    if (NR==0) { print "no replies"; exit 1 }
    p = int(0.95*NR); if (p < 0.95*NR) p++
    printf "n=%d min=%.2f avg=%.2f p95=%.2f max=%.2f ms\n", NR, v[1], s/NR, v[p], v[NR]
  }'
